#include "bootstrap_v2.h"
#include <algorithm>
#include <limits>
namespace recovery::v2::bootstrap {namespace {
constexpr std::uint32_t Magic=0x32425449;
struct Writer {Wire& out;std::size_t at{};void n(std::uint64_t value,unsigned width){for(unsigned i=0;i<width;++i)out[at++]=std::uint8_t(value>>(i*8));}template<class T>void a(const T& values){for(auto c:values)out[at++]=std::uint8_t(c);}};
struct Reader {std::span<const std::uint8_t> in;std::size_t at{};std::uint64_t n(unsigned width){std::uint64_t value{};for(unsigned i=0;i<width;++i)value|=std::uint64_t(in[at++])<<(i*8);return value;}template<class T>void a(T& values){for(auto& c:values)c=static_cast<typename T::value_type>(in[at++]);}};
void identity(Writer& w,const SessionIdentity& i){w.a(i.session);w.a(i.boot);w.a(i.unit);w.a(i.owner);w.a(i.invocation);w.a(i.ownerInvocation);w.a(i.group);w.a(i.mount);w.n(i.device,8);w.n(i.inode,8);w.n(i.ownerPid,4);w.n(i.mainPid,4);w.a(i.ticket);}
void identity(Reader& r,SessionIdentity& i){r.a(i.session);r.a(i.boot);r.a(i.unit);r.a(i.owner);r.a(i.invocation);r.a(i.ownerInvocation);r.a(i.group);r.a(i.mount);i.device=r.n(8);i.inode=r.n(8);i.ownerPid=r.n(4);i.mainPid=r.n(4);r.a(i.ticket);}
void clock(Writer& w,ClockPair c){w.n(c.monotonic,8);w.n(c.boottime,8);w.n(c.generation,8);}void clock(Reader& r,ClockPair& c){c.monotonic=r.n(8);c.boottime=r.n(8);c.generation=r.n(8);}
bool label(const std::array<char,129>& a){auto zero=std::find(a.begin(),a.end(),0);return zero!=a.begin()&&zero!=a.end()&&std::all_of(a.begin(),zero,[](char c){return c>=33&&c<=126;})&&std::all_of(zero,a.end(),[](char c){return c==0;});}
bool shape(const Packet& p){if(!validIdentity(p.identity)||!label(p.profile)||!p.generation||p.generation==std::numeric_limits<std::uint64_t>::max()||!p.started.monotonic||p.started.boottime<p.started.monotonic||!p.started.generation)return false;if(p.kind<Kind::Hello||p.kind>Kind::WitnessAck)return false;
 if(p.kind==Kind::WitnessOffer||p.kind==Kind::Receipt||p.kind==Kind::WitnessAck){if(p.closure.identity!=p.identity||p.closure.generation!=p.generation)return false;Message m;m.kind=recovery::v2::Kind::Closure;m.identity=p.identity;m.generation=p.generation;m.sequence=p.closure.lastGrantSequence;m.closure=p.closure;Wire test;if(!recovery::v2::encode(m,test))return false;return p.kind!=Kind::WitnessOffer?p.witnessPid>1&&p.drained:!p.witnessPid&&!p.drained;}
 return p.closure==ClosureProof{}&&!p.witnessPid&&!p.drained;
}
bool timely(ClockPair start,ClockPair now,const Timing& t){if(!validTiming(t)||now.generation!=start.generation||now.monotonic<start.monotonic||now.boottime<start.boottime)return false;auto mono=now.monotonic-start.monotonic,boot=now.boottime-start.boottime;return mono<t.startupBudget&&boot<t.startupBudget&&(mono>boot?mono-boot:boot-mono)<=t.clockSkew;}
}
bool encode(const Packet& p,Wire& out)noexcept{out.fill(0);if(!shape(p))return false;Writer w{out};w.n(Magic,4);w.n(2,2);w.n(std::uint16_t(p.kind),2);w.n(WireBytes,4);w.n(0,4);identity(w,p.identity);w.a(p.profile);w.n(p.generation,8);clock(w,p.started);w.n(p.closure.generation,8);w.n(p.closure.closureGeneration,8);w.n(p.closure.lastGrantSequence,8);clock(w,p.closure.closedAt);clock(w,p.closure.proofUntil);w.n(std::uint16_t(p.closure.reason),2);w.n(p.closure.originalReference,1);w.n(p.closure.clockReliable,1);w.n(p.witnessPid,4);w.n(p.drained,1);return w.at<=WireBytes;}
std::optional<Packet> decode(std::span<const std::uint8_t> raw)noexcept{if(raw.size()!=WireBytes)return {};Reader r{raw};if(r.n(4)!=Magic||r.n(2)!=2)return {};Packet p;p.kind=Kind(r.n(2));if(r.n(4)!=WireBytes||r.n(4))return {};identity(r,p.identity);r.a(p.profile);p.generation=r.n(8);clock(r,p.started);p.closure.generation=r.n(8);p.closure.closureGeneration=r.n(8);p.closure.lastGrantSequence=r.n(8);clock(r,p.closure.closedAt);clock(r,p.closure.proofUntil);p.closure.reason=Reason(r.n(2));auto reference=r.n(1),reliable=r.n(1);if(reference>1||reliable>1)return {};p.closure.originalReference=reference;p.closure.clockReliable=reliable;p.witnessPid=r.n(4);auto drained=r.n(1);if(drained>1)return {};p.drained=drained;if(p.kind==Kind::WitnessOffer||p.kind==Kind::Receipt||p.kind==Kind::WitnessAck)p.closure.identity=p.identity;while(r.at<raw.size())if(r.n(1))return {};return shape(p)?std::optional<Packet>(p):std::nullopt;}
bool Child::offer(const Packet& p,VerifiedPeer owner,const SessionIdentity& local,std::string_view profile,ClockPair now,const Timing& t)noexcept{if(sealed_||offered_||p.kind!=Kind::Offer||!shape(p)||p.identity!=local||p.profile.data()!=profile||!owner.verified||!owner.connection||owner.uid!=0||owner.pid!=local.ownerPid||!timely(p.started,now,t)){close();return false;}offer_=p;owner_=owner;offered_=true;return true;}
std::optional<Packet> Child::acknowledgement()const noexcept{if(!offered_||permitted_||sealed_)return {};auto p=offer_;p.kind=Kind::Acknowledged;return p;}
bool Child::permit(const Packet& p,VerifiedPeer owner,ClockPair now,const Timing& t)noexcept{auto expected=offer_;expected.kind=Kind::Permit;if(sealed_||!offered_||permitted_||p!=expected||!owner.verified||owner.connection!=owner_.connection||owner.uid!=owner_.uid||owner.pid!=owner_.pid||!timely(offer_.started,now,t)){close();return false;}permitted_=true;return true;}
}
